// Obtenemos todos los registros devueltos por Google Sheets
const items = $input.all();

// Filtramos solo los que tengan status 'listo_prioritario' o 'listo'
const candidatos = items
  .map(i => i.json)
  .filter(j => j && (j.status === 'listo_prioritario' || j.status === 'listo'));

// Si no hay ninguno listo para publicar, retornamos found = false
if (candidatos.length === 0) {
  return [{ json: { found: false } }];
}

// Ordenamiento por Prioridad Dinámica:
// 1° Los que tengan status 'listo_prioritario'
// 2° En caso de empate en status, orden cronológico FIFO (fecha más antigua primero)
candidatos.sort((a, b) => {
  const prioA = a.status === 'listo_prioritario' ? 1 : 0;
  const prioB = b.status === 'listo_prioritario' ? 1 : 0;

  if (prioA !== prioB) {
    return prioB - prioA; // Mayor prioridad primero
  }

  // Si ambos son prioritarios o ambos son normales, FIFO por fecha
  return new Date(a.fecha) - new Date(b.fecha);
});

// Tomamos el ganador de la cola
const postElegido = candidatos[0];

return [{
  json: {
    found: true,
    ...postElegido
  }
}];

const original = $('8. Guardar en Contenido').first().json;
const response = $input.first().json;

const traduccion = response?.candidates?.[0]?.content?.parts?.[0]?.text || '';

if (!traduccion.trim()) {
  throw new Error('Gemini no devolvió una traducción válida.');
}

return [
  {
    json: {
      link: original.link || '',
      texto_original: original.texto_original || '',
      imagen_original: original.imagen_original || '',
      watermark: original.watermark || '',
      texto_final: traduccion.trim(),
      status: 'traducido',
      fecha: original.fecha || '',
      fecha_programada: original.fecha_programada || ''
    }
  }
];

