const input = $input.first().json;

// 1. Obtener el link SEGÚN EL NOMBRE DE TU TRIGGER
// Sustituí '1. Telegram Trigger' por el nombre exacto que veas en tu workflow
const triggerNodeName = '1. Telegram Trigger'; // <--- CAMBIAR ESTO
const link = $(triggerNodeName).first().json.message.text || '';

// 2. Construir el string HTML
const html = input.data || input.body || input;
const htmlStr = typeof html === 'string' ? html : JSON.stringify(html);

// 3. Función getMeta CON FIX DE REGEX (para que no corte en el apóstrofe)
function getMeta(property) {
  const regex = new RegExp(
    `<meta[^>]+property=[\"']${property}[\"'][^>]+content="([^\"]*)"`,
    'i'
  );

  const match = htmlStr.match(regex);

  if (!match) return '';

  return match[1]
    .replace(/&amp;/g, '&')
    .replace(/&quot;/g, '\"')
    .replace(/&#39;/g, "'")
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>');
}

// 4. Obtener og:description
let texto = getMeta('og:description');
let textoFinal = texto;

// 5. Fallback si og:description está vacío (busca name="description")
if (!texto) {
  const nameDescMatch = htmlStr.match(/<meta[^>]+name=[^>]+content=[^>]+>/i);
  textoFinal = nameDescMatch ? nameDescMatch[0].match(/content=[^>]+>(.+)<\/content>/i)?.[1] : '';
}

// 6. Obtener imagen
const imagen = getMeta('og:image');

// 7. Devolver el item (con link incluido)
return [
  {
    json: {
      link: link || '',
      texto_original: textoFinal || '',
      imagen_original: imagen || '',
      watermark: '',
      texto_final: '',
      status: 'extraido',
      fecha: new Date().toISOString()
    }
  }
];

const datosOriginales = $('7. Extraer texto e imagen').first().json;
const filas = $input.all();

let maxNum = 0;

for (const fila of filas) {
  const idFila = (fila.json.id_fila || '').toString().trim();
  const match = idFila.match(/^post(\d+)$/i);
  if (match) {
    const num = parseInt(match[1], 10);
    if (num > maxNum) maxNum = num;
  }
}

const siguienteId = 'post' + (maxNum + 1);

return [
  {
    json: {
      ...datosOriginales,
      id_fila: siguienteId
    }
  }
];

