// Leemos todas las filas devueltas por Google Sheets (los 221 items)
const filas = $input.all();

// Obtenemos el texto original que enviaste a Telegram
let msgText = '';
try {
  msgText = $('1. Telegram Trigger').first().json.message?.text || '';
} catch (e) {
  try {
    msgText = $('1. Telegram Trigger1').first().json.message?.text || '';
  } catch (err) {
    msgText = '';
  }
}

let maxNum = 0;

for (const fila of filas) {
  const idVal = (fila.json?.id_fila || '').toString().trim();
  const match = idVal.match(/post(\d+)/i);
  if (match) {
    const num = parseInt(match[1], 10);
    if (!isNaN(num) && num > maxNum) {
      maxNum = num;
    }
  }
}

// Si la última era post218, el siguiente será post219
const siguienteNum = maxNum > 0 ? maxNum + 1 : 1;
const siguienteId = 'post' + siguienteNum;

return [
  {
    json: {
      id_fila: siguienteId,
      link: "Post escrito",
      texto_original: msgText,
      imagen_original: '',
      watermark: '',
      texto_final: '',
      status: 'extraido',
      fecha: new Date().toISOString()
    }
  }
];

const original = $('Propio - 8. Guardar en Contenido').first().json;
const resJson = $input.first().json;

let rawText = resJson?.candidates?.[0]?.content?.parts?.[0]?.text || '';

// 1. Limpiar bloques markdown de código si vienen incluidos
rawText = rawText.replace(/```json/gi, '').replace(/```/g, '').trim();

let postTexto = '';
let promptVisual = '';

// 2. Intento de parseo estándar
try {
  const parsed = JSON.parse(rawText);
  postTexto = parsed.post_texto || '';
  promptVisual = parsed.prompt_visual || '';
} catch (e1) {
  // 3. Si falla por saltos de línea crudos dentro del string, intentamos normalizarlos
  try {
    const sanitized = rawText.replace(/[\r\n]+/g, '\\n');
    const parsed = JSON.parse(sanitized);
    postTexto = parsed.post_texto || '';
    promptVisual = parsed.prompt_visual || '';
  } catch (e2) {
    // 4. Extracción por Regex de respaldo si el JSON viene con caracteres de control rotos
    const postMatch = rawText.match(/"post_texto"\s*:\s*"([\s\S]*?)"\s*,\s*"prompt_visual"/i);
    const visualMatch = rawText.match(/"prompt_visual"\s*:\s*"([\s\S]*?)"\s*\}/i);

    if (postMatch && visualMatch) {
      postTexto = postMatch[1];
      promptVisual = visualMatch[1];
    } else {
      postTexto = rawText;
      promptVisual = 'Diagrama arquitectónico en Excalidraw';
    }
  }
}

// 5. Desescapar saltos de línea para que en Google Sheets y LinkedIn se lean como texto formateado real
postTexto = postTexto
  .replace(/---\?/g, '---')
  .replace(/\\n/g, '\n')
  .replace(/\\"/g, '"')
  .trim();

promptVisual = promptVisual
  .replace(/\\n/g, ' ')
  .replace(/\\"/g, '"')
  .trim();

return [
  {
    json: {
      link: original.link || 'Post escrito',
      id_fila: original.id_fila || '',
      texto_original: original.texto_original || '',
      imagen_original: original.imagen_original || '',
      watermark: promptVisual,
      texto_final: postTexto,
      status: 'generado',
      fecha: original.fecha || '',
      fecha_programada: original.fecha_programada || '',
      prompt_visual: promptVisual
    }
  }
];
